    compatHead: { same: (a, b) => a + ' und ' + b + ' haben dasselbe Sternzeichen und verstehen vieles intuitiv ähnlich. Das kann sehr stimmig sein, solange ihr euch nicht gegenseitig in denselben Schwächen verstärkt.', opposite: (a, b) => a + ' und ' + b + ' liegen sich im Tierkreis gegenüber. Das kann starke Anziehung schaffen, braucht aber auch Ausgleich, weil ihr vieles aus entgegengesetzten Blickwinkeln angeht.', good: (a, b) => a + ' und ' + b + ' gelten in der Astrologie oft als harmonische Kombination.', ok: (a, b) => a + ' und ' + b + ' können gut zusammenpassen. Eure Elemente sind verschieden, können sich aber gegenseitig unterstützen.', work: (a, b) => a + ' und ' + b + ' können funktionieren, brauchen aber etwas mehr Verständnis füreinander. Die Zeichen stehen im Quadrat und geraten deshalb leichter darüber aneinander, wie etwas laufen sollte.', neutral: (a, b) => a + ' und ' + b + ' sind astrologisch eher eine neutrale Kombination: weder besonders mühelos noch besonders konfliktreich.'},
